namespace Erp.BuildingBlocks.Domain.Entities;

// Standard column sets of the data design (docs/data-design/README.md, "Traits"). Generated entities implement the
// interfaces that match their traits, so shared code (repositories, auditing) can treat them alike.

/// <summary>A row with a single UUIDv7 <c>id</c> key generated by the application.</summary>
public interface IEntity
{
    Guid Id { get; set; }
}

/// <summary>Traits std and app: <c>created_at</c>, <c>created_by</c>.</summary>
public interface ICreationAudited
{
    DateTimeOffset CreatedAt { get; set; }

    Guid CreatedBy { get; set; }
}

/// <summary>Trait std: <c>updated_at</c>, <c>updated_by</c> and the optimistic-concurrency <c>row_version</c>.</summary>
public interface IVersioned
{
    DateTimeOffset UpdatedAt { get; set; }

    Guid UpdatedBy { get; set; }

    long RowVersion { get; set; }
}

/// <summary>Trait soft: master data is never physically deleted.</summary>
public interface ISoftDeletable
{
    bool IsDeleted { get; set; }

    DateTimeOffset? DeletedAt { get; set; }

    Guid? DeletedBy { get; set; }
}

/// <summary>Trait co: the row belongs to one legal entity (company).</summary>
public interface ICompanyScoped
{
    Guid CompanyId { get; set; }
}

/// <summary>Trait app: rows are never updated or deleted; corrections are new rows.</summary>
public interface IAppendOnly;
